import ast, collections

with open('python/synapse/core/aliases.py', 'r') as f:
    content = f.read()

# Find PARAM_ALIASES dict
tree = ast.parse(content)
for node in ast.walk(tree):
    if isinstance(node, ast.Assign):
        for target in node.targets:
            if isinstance(target, ast.Name) and target.id == 'PARAM_ALIASES':
                # Eval the dict
                aliases = eval(compile(ast.Expression(node.value), '<>', 'eval'))
                # Check collisions
                seen = {}
                collisions = collections.defaultdict(list)
                for canonical, alias_list in aliases.items():
                    for alias in alias_list:
                        if alias in seen:
                            collisions[alias].append((seen[alias], canonical))
                        seen[alias] = canonical
                if collisions:
                    print('REMAINING COLLISIONS:')
                    for alias, pairs in sorted(collisions.items()):
                        canons = [p[0] for p in pairs] + [pairs[-1][1]]
                        print(f'  \"{alias}\" -> {canons}')
                else:
                    print('No collisions found!')
                break
